namespace ImplementationDetails {
    struct SymbolEntry { int id; };
}

// Extension 1: Definition in Header context
namespace ImplementationDetails {
    void register_symbol(SymbolEntry s);
}

// Extension 2: Definition in Source context
// Compilers merge these declarations into one logical entity.
namespace ImplementationDetails {
    struct LookupTable { SymbolEntry entries[10]; };
}

// Usage demonstrates merged scope resolution
void lookup_driver() {
    ImplementationDetails::LookupTable t;
    ImplementationDetails::SymbolEntry e;
    ImplementationDetails::register_symbol(e);
}
